  private arg(a: Arg, env: Env, rep: number): number {
    return this.ev(a.e, env, rep, a.at);
  }

  private cond(c: Cond, env: Env, rep: number): boolean {
    const l = this.ev(c.l, env, rep, c.at);
    const r = this.ev(c.r, env, rep, c.at);
    switch (c.op) {
      case "<": return l < r;
      case ">": return l > r;
      case "=": return l === r;
      case "<=": return l <= r;
      case ">=": return l >= r;
      default: return l !== r;
    }
  }

