    this.mark = mark;
    this.paint();
    if (mark && reveal) this.revealLine(mark.line);
  }

  setExecLine(line: number, reveal = true): void {
    if (line === this.execLine) return;
    this.execLine = line;
    this.paintLines();
    if (line && reveal) this.revealLine(line);
