const TOL = 2.5;

function sample(segs: Segment[], step: number): Vec[] {
  const out: Vec[] = [];
  for (const s of segs) {
    const d = Math.hypot(s.to[0] - s.from[0], s.to[1] - s.from[1], s.to[2] - s.from[2]);
    const n = Math.max(1, Math.ceil(d / step));
    for (let i = 0; i <= n; i++) {
      const t = i / n;
