  const ub = bbox(user);
  const size = (b: { min: Vec; max: Vec }) => Math.hypot(b.max[0] - b.min[0], b.max[1] - b.min[1], b.max[2] - b.min[2]);
  const ratio = size(ub) / Math.max(1e-9, size(tb));
  if (ratio > 0 && Math.abs(ratio - 1) > 0.04) {
