}

function compareExact(user: Segment[], target: Segment[], mode: Mode, step: number, tPts: Vec[], tc: Vec): boolean {
  for (const xf of transforms(mode)) {
    const turned = apply(user, xf, [0, 0, 0]);
    const ub = bbox(turned);
