import { chromium } from "playwright";
const base = process.env.URL || "http://localhost:4173/Logomocja/builds/x/";
const browser = await chromium.launch();
const errors = [];
async function page(opts) {
  const ctx = await browser.newContext(opts);
  const p = await ctx.newPage();
  p.on("pageerror", (e) => errors.push("pageerror: " + e.message));
  p.on("console", (m) => { if (m.type() === "error") errors.push("console: " + m.text()); });
  p.on("requestfailed", (r) => errors.push("reqfail: " + r.url()));
  p.on("response", (r) => { if (r.status() >= 400) errors.push(r.status() + " " + r.url()); });
  await p.goto(base);
  await p.waitForFunction(() => window.logomocja);
  return p;
}
const d = await page({ viewport: { width: 1280, height: 800 } });
console.log("version", await d.evaluate(() => window.logomocja.version));
const ex = await d.evaluate(() => window.logomocja.examples);
await d.screenshot({ path: "/tmp/pw/shots/00-initial.png" });
for (const e of ex) {
  // load via the examples dialog, then via open
  const r = await d.evaluate(async (id) => {
    document.getElementById("btn-examples").click();
    document.querySelector(`[data-example="${id}"]`).click();
    await new Promise((r) => setTimeout(r, 50));
    const src = document.querySelector("textarea").value;
    const mode = document.body.dataset.mode;
    const res = await window.logomocja.open(src, mode);
    return { n: res.segments.length, err: res.error, mode, status: document.getElementById("status").textContent };
  }, e.id);
  console.log(e.id, JSON.stringify(r));
  await d.screenshot({ path: `/tmp/pw/shots/ex-${e.id}.png` });
}
// error display
await d.evaluate(() => window.logomocja.open("np 100\npw 90\nnp 10 -5\n", "2d"));
await d.screenshot({ path: "/tmp/pw/shots/10-parse-error.png" });
await d.evaluate(() => window.logomocja.open("powtorz 5 [np 50 pw 72]\nnp 100 / 0\n", "2d"));
await d.screenshot({ path: "/tmp/pw/shots/11-runtime-error.png" });
// stepping
await d.evaluate(() => window.logomocja.open("powtorz 4 [\n  np 100\n  pw 90\n]\n", "2d"));
for (let i = 0; i < 4; i++) await d.click("#btn-step");
console.log("step status:", await d.textContent("#status"), "| readout:", await d.textContent("#readout"));
await d.screenshot({ path: "/tmp/pw/shots/12-step.png" });
// animated run + pause
await d.fill("#speed", "4"); 
await d.evaluate(() => { const s = document.getElementById("speed"); s.value = "5"; s.dispatchEvent(new Event("input")); });
await d.click("#btn-run"); await d.waitForTimeout(400); await d.click("#btn-pause");
console.log("paused:", await d.textContent("#status"));
await d.keyboard.press("Control+Enter"); await d.waitForTimeout(1500);
console.log("after resume:", await d.textContent("#status"));
// pages
await d.goto(base + "#/wyzwania"); await d.waitForTimeout(100);
await d.screenshot({ path: "/tmp/pw/shots/20-challenges.png" });
await d.goto(base + "#/wyzwania/trojkat"); await d.waitForTimeout(100);
