function plural(n: number): string {
  const m10 = n % 10, m100 = n % 100;
  if (n === 1) return "1 odcinek";
  if (m10 >= 2 && m10 <= 4 && !(m100 >= 12 && m100 <= 14)) return `${n} odcinki`;
  return `${n} odcinków`;
}

