(PORT=4174 bun run serve.ts >/dev/null 2>&1 &) ; sleep 1
cd /tmp/pw && cat > fin.mjs <<'E'
import { chromium } from "playwright";
const b = await chromium.launch(); const d = await b.newPage(); const errs = [];
d.on("pageerror", (e) => errs.push(e.message)); d.on("console", (m) => m.type() === "error" && errs.push(m.text())); d.on("requestfailed", (r) => errs.push(r.url())); d.on("response", (r) => r.status() >= 400 && errs.push(r.status() + " " + r.url()));
await d.goto("http://localhost:4174/"); await d.waitForFunction(() => window.logomocja);
const r = await d.evaluate(() => window.logomocja.open('kolor "#FF0000" np 10 gora 90 np 5 np 1/0', "3d"));
console.log(JSON.stringify(r), JSON.stringify(await d.evaluate(() => window.logomocja.run("np 10 pw 90 np 10", "2d"))), errs);
await b.close();
E
